import React, { useState } from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";

import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";

function AppRouter() {
  const [formData, setFormData] = useState({
    incomeType: "",
    questionnaire: {},
    spendingPriority: {}
  });

  const updateData = (newData) => {
    setFormData((prev) => ({ ...prev, ...newData }));
  };

  const handleSave = async (limits) => {
    const finalData = {
      incomeCategory: formData.incomeType,
      questionnaire: formData.questionnaire,
      spendingPriorities: formData.spendingPriority,
      budgetLimits: limits
    };

    try {
      const res = await fetch("http://localhost:5000/save-budget", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(finalData)
      });

      const data = await res.json();
      alert(data.message || "Saved!");
    } catch (err) {
      alert("Server connection failed");
    }
  };

  return (
    <BrowserRouter>
      <Routes>
        <Route
          path="/"
          element={<IncomeCategory updateData={updateData} />}
        />

        <Route
          path="/questionnaire"
          element={<Questionnaire updateData={updateData} />}
        />

        <Route
          path="/spending"
          element={<SpendingPriority updateData={updateData} />}
        />

        <Route
          path="/budget"
          element={
            <BudgetLimits
              categories={
                Object.keys(formData.spendingPriority || {}).filter(
                  (cat) => formData.spendingPriority[cat] >= 3
                )
              }
              onSave={handleSave}
            />
          }
        />

        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </BrowserRouter>
  );
}

export default AppRouter;
